import{R as t,e as s,f as a,U as o}from"./chunks/framework.ywem4qy5.js";const h=JSON.parse('{"title":"Save & Continue Later","description":"","frontmatter":{},"headers":[],"relativePath":"forms/save-continue-later.md","filePath":"forms/save-continue-later.md","lastUpdated":1775908585000}'),n={name:"forms/save-continue-later.md"};function i(r,e,l,m,p,u){return s(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="save-continue-later" tabindex="-1">Save &amp; Continue Later <a class="header-anchor" href="#save-continue-later" aria-label="Permalink to &quot;Save &amp; Continue Later&quot;">​</a></h1><p>Formie stores all submissions in the database, including incomplete ones.</p><p>That means there are two related things happening when someone does not finish a form in one go. Formie can keep track of in-progress submissions automatically, and you can optionally show a save button that creates a resume link for later.</p><p>This is especially useful on longer forms, multi-page forms, and any workflow where someone may need to stop and come back later.</p><h2 id="incomplete-submissions" tabindex="-1">Incomplete submissions <a class="header-anchor" href="#incomplete-submissions" aria-label="Permalink to &quot;Incomplete submissions&quot;">​</a></h2><p>Incomplete submissions are real saved records, not a separate content type. On multi-page forms, progress is saved as someone moves from one page to the next. Until the final step is completed, the submission stays incomplete.</p><p>This happens whether or not you show a save button. It means you can review partial or abandoned submissions in the control panel, and it also gives Formie something to resume later.</p><p>If <code>Automatic Submission State</code> is enabled on the form, someone returning to that form can continue their in-progress submission automatically. If it is disabled, the form starts fresh unless they open a resume link.</p><p>Incomplete submissions are still different from completed submissions, so they are often handled differently for reporting, exports, follow-up, and cleanup. You can manage those records in <a href="/submissions/statuses">Statuses</a>.</p><h2 id="save-button-and-resume-links" tabindex="-1">Save button and resume links <a class="header-anchor" href="#save-button-and-resume-links" aria-label="Permalink to &quot;Save button and resume links&quot;">​</a></h2><p>If you want someone to deliberately save their place, enable <code>Show Save Button</code> on the page where that option should appear. When someone uses it, Formie creates a resume link with a token tied to that in-progress submission.</p><p>Opening that link loads the saved submission again so the person can continue where they left off. The link is not limited to the same browser or device, so it can be reopened later elsewhere, or passed to someone else if that is part of your process.</p><p>You can also control the save button label and whether it appears as a link or a button in the page settings.</p><div class="warning custom-block github-alert"><p class="custom-block-title">WARNING</p><p>Anyone with a resume link can continue that in-progress submission. Treat the link like private access to the draft, especially on forms that collect personal or sensitive information.</p></div><h2 id="retention-and-expiry" tabindex="-1">Retention and expiry <a class="header-anchor" href="#retention-and-expiry" aria-label="Permalink to &quot;Retention and expiry&quot;">​</a></h2><p>Resume links expire based on the <code>saveResumeTokenTtlDays</code> plugin setting in <a href="/get-started/configuration">Configuration</a>. Incomplete submissions are also affected by the <code>maxIncompleteSubmissionAge</code> plugin setting, and the form’s own <code>Data Retention</code> settings in <a href="/forms/form-builder">Form Builder</a> can affect how long submission data is kept.</p><p>If someone may come back after days or weeks, make sure those settings allow enough time for both the saved submission and the resume link to still be available.</p>',17)])])}const d=t(n,[["render",i]]);export{h as __pageData,d as default};
